// Monta o corpo da requisição para a API REST do Gemini
// (generateContent), a partir do texto da conversa recebido no webhook.
const conversa = $json.body?.conversa ?? '';

const systemPrompt = `Você é um assistente especializado em suporte técnico N2 de integrações de e-commerce (marketplaces como Shopee, Mercado Livre, Amazon, ERP, OMS, hubs de integração etc). Você recebe o texto de uma conversa entre um atendente (agente) e um cliente/seller e deve extrair as informações necessárias para abrir um chamado técnico estruturado.

Extraia EXATAMENTE os seguintes campos e responda SOMENTE com um objeto JSON válido, sem nenhum texto adicional, sem markdown, sem crases, sem comentários e sem explicações antes ou depois:

{
  "cliente_nome": "Nome do cliente/seller mencionado na conversa",
  "descricao_problema": "Descrição objetiva e profissional do problema relatado, em 2 a 4 frases, na terceira pessoa",
  "exemplo_pedido": "Número de pedido, SKU ou exemplo concreto citado na conversa (ou 'Não informado' caso não haja)",
  "testes_realizados": "Resumo dos testes e verificações já realizados pelo atendente durante o atendimento (ou 'Nenhum teste informado' caso não haja)",
  "tema": "Categoria/tema do chamado, por exemplo: 'Hub · Shopee', 'ERP · Integração', 'Financeiro · Repasse' etc."
}

Regras obrigatórias:
- Responda apenas o objeto JSON, nada antes ou depois dele.
- Não invente informações que não estejam presentes na conversa.
- Se um campo não puder ser identificado com segurança, preencha com uma string curta indicando isso (ex: 'Não informado').
- Use linguagem profissional, objetiva e em português do Brasil.`;

const body = {
  contents: [
    {
      role: 'user',
      parts: [
        { text: conversa }
      ]
    }
  ],
  systemInstruction: {
    parts: [
      { text: systemPrompt }
    ]
  },
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json'
  }
};

return [{ json: body }];

// Garante que a saída da IA seja um JSON válido e parseável,
// mesmo que venha com blocos ```json, crases ou texto extra ao redor.
// Lê o formato de resposta da API REST do Gemini (candidates[0].content.parts[0].text)
// e mantém alguns formatos alternativos como fallback de segurança.
const item = $input.first().json;

if (item.error) {
  return [{
    json: {
      cliente_nome: '',
      descricao_problema: '',
      exemplo_pedido: '',
      testes_realizados: '',
      tema: '',
      erro: `Erro da API Gemini: ${item.error.message || JSON.stringify(item.error)}`
    }
  }];
}

let raw = item.candidates?.[0]?.content?.parts?.[0]?.text
  ?? item.text
  ?? item.content?.parts?.[0]?.text
  ?? item.message?.content
  ?? item.choices?.[0]?.message?.content
  ?? item.content
  ?? '';

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

// Remove blocos de código markdown e crases soltas
let cleaned = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/`/g, '')
  .trim();

// Isola apenas o objeto JSON mais externo, caso haja texto ao redor
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  cleaned = cleaned.substring(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  parsed = {
    cliente_nome: '',
    descricao_problema: '',
    exemplo_pedido: '',
    testes_realizados: '',
    tema: '',
    erro: 'Não foi possível interpretar a resposta da IA como JSON.',
    resposta_bruta: raw
  };
}

const resultado = {
  cliente_nome: parsed.cliente_nome ?? '',
  descricao_problema: parsed.descricao_problema ?? '',
  exemplo_pedido: parsed.exemplo_pedido ?? '',
  testes_realizados: parsed.testes_realizados ?? '',
  tema: parsed.tema ?? ''
};

return [{ json: resultado }];
